C","Zone A","Zone B","Zone B","Zone B","Zone B","Zone B","Zone B","Zone B","Zone B","Zone A","Zone B","Zone A","Zone A","Zone A","Zone B","Zone B","Zone B","Zone A","Zone C","Zone A","Zone C","Zone B","Zone C","Zone A","Zone B","Zone A","Zone B","Zone B","Zone C","Zone C","Zone B","Zone A","Zone C","Zone A","Zone B","Zone C","Zone C","Zone C","Zone C","Zone A","Zone A","Zone B","Zone B","Zone A","Zone A","Zone C","Zone B","Zone A","Zone C","Zone B","Zone C","Zone B","Zone C","Zone C","Zone A","Zone B","Zone B","Zone B","Zone A","Zone A","Zone A","Zone B","Zone B","Zone B","Zone A","Zone A","Zone A","Zone B","Zone C","Zone B","Zone C","Zone A","Zone A","Zone B","Zone B","Zone B","Zone B","Zone C","Zone C","Zone B","Zone A","Zone C","Zone A","Zone C","Zone A","Zone C","Zone A","Zone C","Zone B","Zone B","Zone C","Zone B","Zone A","Zone B","Zone B","Zone A","Zone A","Zone C","Zone C","Zone B","Zone C","Zone A","Zone A","Zone C","Zone A","Zone C","Zone C","Zone A","Zone C","Zone A","Zone C","Zone A","Zone B","Zone A","Zone A","Zone A","Zone A","Zone B","Zone C","Zone C","Zone C","Zone C","Zone B","Zone A","Zone A","Zone A","Zone C","Zone B","Zone A","Zone C","Zone C","Zone B","Zone A","Zone C","Zone C","Zone C","Zone C","Zone B","Zone C","Zone B","Zone A","Zone A","Zone A","Zone C","Zone A","Zone C","Zone A","Zone B","Zone A","Zone B","Zone A","Zone C","Zone B","Zone C","Zone B","Zone B","Zone A","Zone C","Zone A","Zone B","Zone C","Zone C","Zone B","Zone A","Zone C","Zone A","Zone C","Zone C","Zone A","Zone B","Zone C","Zone B","Zone B","Zone A","Zone C","Zone B","Zone C","Zone A","Zone A","Zone B","Zone A","Zone B","Zone A","Zone B","Zone A","Zone B","Zone C","Zone B","Zone B","Zone B","Zone C","Zone A","Zone A","Zone A","Zone C","Zone B","Zone A","Zone A","Zone B","Zone A","Zone A","Zone C","Zone B","Zone C","Zone B","Zone B","Zone A","Zone B","Zone C","Zone C","Zone B","Zone B","Zone A","Zone B","Zone C","Zone A","Zone B","Zone A","Zone B","Zone A","Zone B","Zone C","Zone B","Zone A","Zone A","Zone B","Zone A","Zone B","Zone B","Zone C","Zone A","Zone A","Zone B","Zone B","Zone A","Zone A","Zone A","Zone C","Zone C","Zone A","Zone B","Zone A","Zone C","Zone B","Zone B","Zone A","Zone C","Zone B","Zone C","Zone C","Zone A","Zone B","Zone A","Zone A","Zone C","Zone C","Zone A","Zone B","Zone A","Zone B","Zone C","Zone C","Zone C","Zone B","Zone B","Zone A","Zone A","Zone B","Zone C","Zone B","Zone A"]}$q$::jsonb;
 summary_formulas jsonb := $q${"Y2":["=COUNTA(B2:B500)",499],"Y3":["=MEDIAN(J2:J500)",49],"Y4":["=SUMPRODUCT(F2:F500,I2:I500)",463893],"Y5":["=COUNTIFS(C2:C500,\"F\",M2:M500,\"Qualified\")",203],"Y6":["=ROUND(AVERAGEIFS(F2:F500,E2:E500,\"SC\"),2)",33.05]}$q$::jsonb;
 patches jsonb := $q${"A1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"B1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"C1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"D1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"E1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"F1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"G1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"H1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"I1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"J1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"K1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"L1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"M1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"N1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"O1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"P1":{"bold":true,"fillColor":"ED7D31","fontColor":"FFFFFF"},"R1":{"bold":true,"fillColor":"5B9BD5","fontColor":"FFFFFF","align":"center"},"S1":{"bold":true,"fillColor":"5B9BD5","fontColor":"FFFFFF","align":"center"},"T1":{"bold":true,"fillColor":"5B9BD5","fontColor":"FFFFFF","align":"center"},"U1":{"bold":true,"fillColor":"5B9BD5","fontColor":"FFFFFF","align":"center"},"V1":{"bold":true,"fillColor":"5B9BD5","fontColor":"FFFFFF","align":"center"},"W1":{"bold":true,"fillColor":"5B9BD5","fontColor":"FFFFFF","align":"center"}}$q$::jsonb;
 questions jsonb := $q$[{"n":1,"marks":3,"text":"Select the table A1:P500 (with its heading) and apply Format as Table using \"Table Style Medium 3\".","solution":"1. Select **A1:P500** (click A1, then **Ctrl+Shift+→** and **Ctrl+Shift+↓**).\n2. HOME → **Format as Table** → **Table Style Medium 3** (the orange one).\n3. In the dialog, keep \"My table has headers\" ticked → **OK**.\n\nChecked: the heading row is bold, orange fill (#ED7D31) with white text, and the data rows below it alternate orange-tint and white banding.","criteria":[{"rule":"cells","range":"A1:P1","props":{"bold":[true],"fillColor":["ED7D31"],"fontColor":["FFFFFF"]}},{"band":true}]},{"n":2,"marks":1,"text":"Fill the Zone table's heading R1:W1 with Theme Colour \"Blue, Accent 1\", white font colour, Bold and Center.","solution":"1. Select **R1:W1** (the row of district names above the Zone row).\n2. HOME → **Bold** (Ctrl+B) and **Center** (Ctrl+E).\n3. HOME → **Fill Color ▾** → **Theme Colors** (top row) → **Blue, Accent 1**.\n4. HOME → **Font Color ▾** → **Theme Colors** → **White, Background 1**.\n\nChecked: R1:W1 bold, centred, filled #5B9BD5 (Blue, Accent 1) with white text.","criteria":[{"rule":"cells","range":"R1:W1","props":{"bold":[true],"fillColor":["5B9BD5"],"fontColor":["FFFFFF"],"align":["center"]}}]},{"n":3,"marks":1,"text":"In column J (Total) find the Total of Written, Interview and GK marks (F to H) for every candidate using the SUM function.","solution":"1. Click **J2** and type **=SUM(F2:H2)** → Enter (48+13+2 = 63).\n2. Double-click the fill handle of J2 to copy the formula down to **J500**.\n\nChecked: a formula in every cell J2:J500 with the right total.","criteria":[{"column":"J"}]},{"n":4,"marks":1,"text":"In column K (Percentage) find the percentage of every candidate. The maximum Total is 80, rounded to 2 decimal places with ROUND.","solution":"1. Click **K2** and type **=ROUND(J2/80*100,2)** → Enter.\n2. Double-click the fill handle to fill down to **K500**.\n\nChecked: every percentage in K2:K500.","criteria":[{"column":"K"}]},{"n":5,"marks":2,"text":"In column L (Grade) using the IFS function give grade on Percentage: 80 or more = \"A+\", 65 or more = \"A\", 50 or more = \"B\", 35 or more = \"C\", otherwise \"D\".","solution":"**IFS** checks each condition in order and returns the result next to the first TRUE one: **=IFS(condition1,result1,condition2,result2,...)**. A final **TRUE** catches everything else.\n1. Click **L2** and type:\n   **=IFS(K2>=80,\"A+\",K2>=65,\"A\",K2>=50,\"B\",K2>=35,\"C\",TRUE,\"D\")** → Enter.\n2. Double-click the fill handle to fill down to **L500**.\n\n**IFS exists only in Excel 2019 / 365, not Excel 2013** — there, write it as nested IF instead: =IF(K2>=80,\"A+\",IF(K2>=65,\"A\",IF(K2>=50,\"B\",IF(K2>=35,\"C\",\"D\")))). Either formula is accepted here.\n\nChecked: the grade in every cell L2:L500.","criteria":[{"column":"L"}]},{"n":6,"marks":1,"text":"In column M (Result) using IF write \"Qualified\" if the Total is 40 or more (>=40), otherwise \"Not Qualified\".","solution":"1. Click **M2** and type **=IF(J2>=40,\"Qualified\",\"Not Qualified\")** → Enter.\n2. Double-click the fill handle to fill down to **M500**.\n\nChecked: every cell M2:M500.","criteria":[{"column":"M"}]},{"n":7,"marks":2,"text":"In column N (Selection) using IF with AND write \"Selected\" if the Result is \"Qualified\" AND the Typing Speed is 30 WPM or more, otherwise \"Not Selected\".","solution":"AND is TRUE only when **every** condition is TRUE.\n1. Click **N2** and type **=IF(AND(M2=\"Qualified\",I2>=30),\"Selected\",\"Not Selected\")** → Enter.\n2. Double-click the fill handle to fill down to **N500**.\n\nChecked: every cell N2:N500.","criteria":[{"column":"N"}]},{"n":8,"marks":2,"text":"In column O (Fee Waiver) using IF with OR write \"Yes\" if the Category is \"SC\" OR \"ST\", otherwise \"No\".","solution":"OR is TRUE when **at least one** condition is TRUE.\n1. Click **O2** and type **=IF(OR(E2=\"SC\",E2=\"ST\"),\"Yes\",\"No\")** → Enter.\n2. Double-click the fill handle to fill down to **O500**.\n\nChecked: every cell O2:O500.","criteria":[{"column":"O"}]},{"n":9,"marks":2,"text":"In column P (Zone) using HLOOKUP find each candidate's Zone from the table R1:W2 (district names in row 1, zone in row 2), based on the District.","solution":"**HLOOKUP** looks up a value across a **horizontal** table (VLOOKUP looks down a vertical one): **=HLOOKUP(lookup_value, table, row_index, FALSE)**.\n1. Click **P2** and type **=HLOOKUP(D2,$R$1:$W$2,2,FALSE)** → Enter.\n2. The table R1:W2 does not move as you fill down, so use **$R$1:$W$2** (press F4 after typing the range to add the $ signs).\n3. Double-click the fill handle to fill down to **P500**.\n\nChecked: every cell P2:P500.","criteria":[{"column":"P"}]},{"n":10,"marks":1,"text":"In cell Y2 count the total number of candidates using COUNTA on Candidate Name.","solution":"**COUNTA** counts every cell that is not empty.\n1. Click **Y2** and type **=COUNTA(B2:B500)** → Enter → 499.\n\nChecked: Y2 with a formula.","criteria":[{"rule":"value","cell":"Y2","equals":499,"formula":true}]},{"n":11,"marks":2,"text":"In cell Y3 find the Median Total using the MEDIAN function.","solution":"**MEDIAN** finds the middle value when the numbers are sorted (not the same as AVERAGE).\n1. Click **Y3** and type **=MEDIAN(J2:J500)** → Enter → 49.\n\nChecked: Y3 with a formula.","criteria":[{"rule":"value","cell":"Y3","equals":49,"formula":true}]},{"n":12,"marks":2,"text":"In cell Y4 find the Admission Index -- the sum of (Written marks x Typing Speed) for every candidate -- using the SUMPRODUCT function.","solution":"**SUMPRODUCT** multiplies two (or more) ranges cell by cell, then adds up all the results in one go -- no helper column needed: **=SUMPRODUCT(range1,range2)**.\n1. Click **Y4** and type **=SUMPRODUCT(F2:F500,I2:I500)** → Enter → 463893.\n\n(The long way: a helper column with =F2*I2 filled down, then =SUM() of that column -- SUMPRODUCT does both steps in one formula.)\n\nChecked: Y4 with a formula.","criteria":[{"rule":"value","cell":"Y4","equals":463893,"formula":true}]},{"n":13,"marks":2,"text":"Using COUNTIFS, in cell Y5 count the girl candidates (Gender = \"F\") whose Result is \"Qualified\".","solution":"**=COUNTIFS(range1,criteria1,range2,criteria2,...)** counts the rows that meet **all** the conditions.\n1. Click **Y5** and type **=COUNTIFS(C2:C500,\"F\",M2:M500,\"Qualified\")** → Enter → 203.\n\nChecked: Y5 with a formula.","criteria":[{"rule":"value","cell":"Y5","equals":203,"formula":true}]},{"n":14,"marks":1,"text":"In cell Y6 find the average Written marks of the SC category candidates using AVERAGEIFS, rounded to 2 decimal places with ROUND.","solution":"**=AVERAGEIFS(average_range,range1,criteria1)** averages only the rows that meet the condition.\n1. Click **Y6** and type **=ROUND(AVERAGEIFS(F2:F500,E2:E500,\"SC\"),2)** → Enter → 33.05.\n\nChecked: Y6 = 33.05 with a formula.","criteria":[{"rule":"value","cell":"Y6","equals":33.05,"formula":true}]},{"n":15,"marks":2,"text":"Freeze the top row of the sheet so the headings stay visible while scrolling, and apply Filter to the table A1:P500.","solution":"1. VIEW → **Freeze Panes ▾** → **Freeze Top Row**.\n2. Click any cell of the table, for example A1. DATA → **Filter** (or **Ctrl+Shift+L**).\n\nDo the Filter step after the formula columns are filled, so it covers the complete table.\n\nChecked: panes frozen below row 1, and a filter on the table.","criteria":[{"rule":"sheet","path":"freeze","equals":"A2"},{"rule":"sheet","path":"filter","in":["A1:A500","A1:B500","A1:C500","A1:D500","A1:E500","A1:F500","A1:G500","A1:H500","A1:I500","A1:J500","A1:K500","A1:L500","A1:M500","A1:N500","A1:O500","A1:P500"]}]}]$q$::jsonb;
 cells jsonb; model_cells jsonb; working jsonb; model jsonb;
begin
 if exists (select 1 from public.excel_efficiency_tests where slug = 'efficiency-test-7') then raise notice 'EXCEL EFFICIENCY TEST 7 already exists'; return; end if;

 select fixed || jsonb_object_agg(chr(65 + i) || (r + 2), pg_temp.excel_cell(candidates->r->i)) into cells
 from generate_series(0, jsonb_array_length(candidates) - 1) r, generate_series(0, 8) i;
 working := jsonb_build_object('schemaVersion', 1, 'language', 'English', 'rows', 500, 'cols', 25, 'cells', cells);
 perform public.assert_excel_efficiency_working_matter(working);

 select cells || jsonb_object_agg(ref, cell) into model_cells from (
   select t.key || (r + 2) as ref, pg_temp.excel_cell(vals->t.key->r, replace(t.value, '#', (r + 2)::text)) as cell from jsonb_each_text(templates) t, generate_series(0, 498) r
   union all select key, pg_temp.excel_cell(value->1, value->>0) from jsonb_each(summary_formulas)) x;
 select model_cells || jsonb_object_agg(key, (model_cells->key) || value) into model_cells from jsonb_each(patches || pg_temp.band_patches());
 model := jsonb_build_object('schemaVersion', '3', 'rows', 500, 'cols', 25, 'cells', model_cells, 'merges', '[]'::jsonb,
   'sheet', $q${"name":"Sheet1","freeze":"A2","filter":"A1:P500","filterHidden":{}}$q$::jsonb, 'operations', '[]'::jsonb, 'savedAt', '2026-11-09T00:00:00.000Z');
 perform public.assert_excel_efficiency_document_schema(model);

 insert into public.excel_efficiency_tests (slug, title, language, status, created_by, sequence, auto_publish_results)
 values ('efficiency-test-7', 'EFFICIENCY TEST 7', 'English', 'draft', admin_id, 7, true) returning id into t_id;
 insert into public.excel_efficiency_versions (test_id, version_number, title, language, description, instructions_markdown, question_count, maximum_marks,
   duration_options, passing_marks, working_matter_snapshot, created_by, delivery_pdf, delivery_onscreen, student_question_toggle, model_answer_snapshot)
 values (t_id, 1, 'EFFICIENCY TEST 7', 'English', 'Advanced level, about 10 minutes: recruitment sheet of 499 candidates -- Theme Colour, Format as Table, IFS, HLOOKUP, SUMPRODUCT, MEDIAN',
   $q$1. Carefully read the instructions and solve the questions accordingly.
2. All questions are mandatory.
3. The sheet has 499 candidates (rows 2 to 500). Fill a formula in row 2, then double-click the fill handle to copy it down to row 500.
4. **Maximum marks** and question-wise marks are shown with the questions.
5. This is an ADVANCED-level paper (Theme Colour, Format as Table, IFS, HLOOKUP, SUMPRODUCT, MEDIAN): you can still finish it in about 10 minutes -- type a formula once and fill it down, the row count does not add extra work. Any method is fine: the answer in the cells is what is checked.$q$, 15, 25, array[600, 900, 1200], 9, working, admin_id, false, true, true, model) returning id into v_id;
 update public.excel_efficiency_tests set current_version_id = v_id, current_version_number = 1 where id = t_id;

 for item in select value from jsonb_array_elements(questions) loop
  crit := '[]'::jsonb;
  for c in select value from jsonb_array_elements(item->'criteria') loop
   if c ? 'column' then crit := crit || pg_temp.column_checks(vals, c->>'column');
   elsif c ? 'band' then crit := crit || jsonb_build_array(jsonb_build_object('rule', 'allOf', 'criteria', pg_temp.band_checks()));
   else crit := crit || jsonb_build_array(c);
   end if;
  end loop;
  insert into public.excel_efficiency_questions (version_id, question_number, instruction, marks, display_order, solution)
  values (v_id, (item->>'n')::int, item->>'text', (item->>'marks')::numeric, (item->>'n')::int, item->>'solution') returning id into q_id;
  insert into public.excel_efficiency_grading_rules (version_id, question_id, exact_target, expected_operation, expected_value, allocated_marks, additional_criteria)
  values (v_id, q_id, 'hand-written', 'rule-criteria', 'null'::jsonb, (item->>'marks')::numeric, crit);
 end loop;
end $mig$;

-- Check: the model answer scores the full marks of every question, the untouched sheet 0.
select q.question_number, q.marks,
  public.excel_efficiency_score_question(v.model_answer_snapshot, v.id, q.id, q.marks) as model,
  public.excel_efficiency_score_question(public.excel_efficiency_initial_editor_document(v.working_matter_snapshot), v.id, q.id, q.marks) as untouched
from public.excel_efficiency_tests t join public.excel_efficiency_versions v on v.id = t.current_version_id
join public.excel_efficiency_questions q on q.version_id = v.id where t.slug = 'efficiency-test-7' order by q.question_number;

commit;
